Nachtlinie.JavaScript:
--!strict
return [==[
(function () {
  var show = document.getElementById('anzeigen');
  if (show) show.addEventListener('click', function () {
    var line = document.getElementById('linie').value;
    var names = { '4': ['Ablage / anonyme Post', 'Nullpost / Ablage', 'Fundbestand 04', '00:13', '00:19', '00:31'], '7': ['Bildbestand / Kanal', 'Restlicht / Bildbestand', 'Kanal Sechs', '02:17', '02:24', '02:38'], '17': ['nicht gelisteter Bereich', 'Knoten ohne Kennung', 'Sitzung M', '03:17', '--:--', '--:--'] };
    var plan = names[line];
    if (!plan) return;
    document.getElementById('plan-title').textContent = 'N' + line + ' · ' + plan[0] + (line === '17' ? ' · unbestätigt' : ' · zuletzt bestätigt');
    document.getElementById('halt-a').textContent = 'einstieg.n' + line;
    document.getElementById('halt-b').textContent = plan[1];
    document.getElementById('halt-c').textContent = plan[2];
    document.getElementById('zeit-a').textContent = plan[3];
    document.getElementById('zeit-b').textContent = plan[4];
    document.getElementById('zeit-c').textContent = plan[5];
    document.getElementById('status-a').textContent = line === '17' ? 'unbestätigt' : 'offen';
    document.getElementById('status-b').textContent = line === '17' ? 'unbekannt' : 'bestätigt';
    document.getElementById('status-c').textContent = line === '17' ? 'gesperrt' : 'bestätigt';
    document.getElementById('auskunft').textContent = line === '17' ? 'N17: Nicht bestätigt. Der Knoten antwortet mit Ihrer Kennung.' : 'N' + line + ' bestätigt. Zwei unabhängige Rückmeldungen.';
  });
  var radio = document.getElementById('protokoll-button');
  if (radio) radio.addEventListener('click', function () {
    document.getElementById('protokoll').textContent = '03:17 / M an Betreiber\n"Ich bin nicht vor dem Fenster. Ich bin in der Aufnahme."\n03:18 / Betreiber an M\n"Dein Zugang ist gesperrt."\n03:19 / M\n"Warum sehe ich dann, was du gerade schreibst?"';
  });
}());
]==]

