Zimmer13.JavaScript:
--!strict
return [==[
(function () {
  var search = document.getElementById('suchen');
  if (search) search.addEventListener('click', function () {
    var room = document.getElementById('zimmer').value;
    var text = 'Dieser Bereich ist im sichtbaren Archiv nicht eingetragen.';
    if (room === '14') text = 'Bereich 14 ist lesbar. Letzter Absender: M.';
    if (room === '13') text = 'Bereich 13: Eine Sitzung ist bereits mit Ihrer Kennung geöffnet.';
    if (room === '1' || room === '01' || room === '7' || room === '07') text = 'Dieser Bereich wurde nach dem Vorfall gesperrt.';
    document.getElementById('zimmer-auskunft').textContent = text;
  });
  var post = document.getElementById('eintragen');
  if (post) post.addEventListener('click', function () {
    var name = document.getElementById('gastname').value;
    var message = document.getElementById('nachricht').value;
    document.getElementById('gast-status').textContent = name && message ? 'Hinweis von ' + name + ' im Archiv abgelegt. Keine öffentliche Antwort.' : 'Bitte Kennung und Hinweis eintragen.';
  });
}());
]==]

