browserFiles.fundbuero-04/app.js:
(function(){
var rows=[['fund-11','mailbox wintergast zeitstempel spiegel'],['fund-13','verzeichnis einladungen empfänger anonym'],['fund-14','übertragungsprotokoll signatur absender k6'],['fund-17','sitzung sitzungsfragment gelöscht m protokoll'],['fund-19','index knoten verschwunden spiegel'],['fund-20','bildbeschreibungen bilder fehlen anonym']];
function filtern(){var term=document.getElementById('suchwort').value.toLowerCase();var count=0;for(var i=0;i<rows.length;i++){var show=rows[i][1].indexOf(term)!==-1;document.getElementById(rows[i][0]).style.display=show?'table-row':'none';if(show)count++;}document.getElementById('treffer').textContent=count+(count===1?' Eintrag im öffentlichen Bestand.':' Einträge im öffentlichen Bestand.');}
document.getElementById('suche').addEventListener('submit',function(event){event.preventDefault();filtern();});
document.getElementById('suchen').addEventListener('click',function(event){event.preventDefault();filtern();});
document.getElementById('alle').addEventListener('click',function(){document.getElementById('suchwort').value='';filtern();});
})();

