document.getElementById('terminal-send').addEventListener('click', function () {
 var command = document.getElementById('terminal-command').value.toLowerCase();
 var answer = 'KEIN TREFFER. Verfügbare Abfragen: hilfe / spiegel / 17.';
 if (command === 'hilfe') answer = 'HILFE\nspiegel — verfügbare Gegenstellen\n17 — zurückgezogene Verbindung';
 if (command === 'spiegel') answer = 'SPIEGEL 02: LESEND\nSPIEGEL 04: ERREICHBAR\nSPIEGEL 17: NICHT MEHR BEI UNS';
 if (command === '17') answer = 'AKTE 17 / M.\nLetzte Gegenstelle: PAPIERMOND.\nEin Empfänger las die Nachricht vor ihrer Absendung.\nZeitstempel: 03:17';
 document.getElementById('terminal-result').textContent = answer;
});

