browserFiles.verzeichnis/styles.css:
html { background: #090b10; color: #b8bac4; }
body { margin: 0; font-family: Georgia, "Times New Roman", serif; font-size: 14px; line-height: 1.45; }
main { width: 730px; max-width: 90%; margin: 24px auto 50px; }
a { color: #9baedb; text-decoration: underline; cursor: pointer; }
a:visited { color: #a18cae; }
a:hover { color: #e5dcbd; }
.mirror, nav, .notice, footer { font-family: "Courier New", monospace; font-size: 11px; }
.mirror { color: #6f7481; border-bottom: 1px solid #333744; padding-bottom: 9px; }
header { text-align: center; padding: 9px 0 15px; }
.mark { margin: 0; color: #6e7794; font: 26px "Courier New", monospace; letter-spacing: 8px; }
h1 { color: #dbdce0; font-size: 29px; font-weight: normal; margin: 5px 0 7px; }
header p { margin: 0; font-size: 12px; color: #9296a3; }
nav { text-align: center; padding: 9px 0; border-top: 1px solid #333744; border-bottom: 1px solid #333744; }
.notice { margin: 15px 0 25px; color: #888b96; }
h2 { font-size: 15px; font-weight: normal; color: #b8b09a; border-bottom: 1px dotted #3e414d; padding-bottom: 4px; margin: 22px 0 12px; }
dl { margin: 0; }
dt { margin-top: 11px; font-size: 15px; }
dd { margin: 2px 0 0 18px; color: #8c919e; font-size: 12px; }
hr { height: 0; border: 0; border-top: 1px solid #333744; margin-top: 25px; }
.closing { font-style: italic; font-size: 12px; color: #8b8c94; }
footer { margin-top: 20px; color: #969ba8; }
footer span { color: #646b78; }
.note { width: 590px; line-height: 1.7; }
.note h1 { font-size: 25px; margin: 25px 0 12px; }
.note p { margin: 20px 0; }
.note .mirror { font-size: 11px; }
.signature { font-style: italic; color: #8b8c94; }
@media (max-width: 520px) { main { margin-top: 14px; } h1 { font-size: 24px; } nav { line-height: 2; } dd { margin-left: 10px; } }

